function limited(request,key,max,windowMs){const ip=request.headers.get('cf-connecting-ip')||'local',id=`${key}:${ip}`,t=now(),row=limits.get(id);if(!row||row.until<t){limits.set(id,{count:1,until:t+windowMs});return false;}return ++row.count>max;}
async function body(request){try{return await request.json();}catch{return null;}}
