function publicUser(u){return {id:u.id,name:u.name,email:u.email,role:u.role,plan:u.plan,hasAvatar:!!u.avatar_key,avatarVersion:u.updated_at,createdAt:u.created_at,lastLoginAt:u.last_login_at,lastActivityAt:u.last_activity_at};}
async function auth(request,env,touch=true){if(!env.DB)return null;const token=cookie(request).fixou_session;if(!token)return null;const hash=await sha(token);const row=await env.DB.prepare(`SELECT u.* FROM auth_sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=? AND s.expires_at>?`).bind(hash,now()).first();if(row&&touch&&(!row.last_activity_at||now()-row.last_activity_at>60000))await env.DB.prepare('UPDATE users SET last_activity_at=? WHERE id=?').bind(now(),row.id).run();return row||null;}
async function event(env,userId,type,metadata={},eventKey=null){if(!env.DB)return;const safe=JSON.stringify(metadata).slice(0,1500);await env.DB.prepare('INSERT OR IGNORE INTO analytics_events(id,user_id,event_type,event_key,metadata_json,created_at) VALUES(?,?,?,?,?,?)').bind(uuid(),userId||null,clean(type,60),eventKey,safe,now()).run();}
async function createSession(env,userId){const token=randomToken();await env.DB.prepare('INSERT INTO auth_sessions(id,user_id,token_hash,created_at,expires_at) VALUES(?,?,?,?,?)').bind(uuid(),userId,await sha(token),now(),now()+SESSION_MS).run();return token;}
async function createUser(env,input,role='student'){const name=clean(input?.name,80),email=clean(input?.email,160).toLowerCase(),password=String(input?.password||'');if(name.length<2||!validEmail(email)||password.length<8||password.length>128)return {error:'Informe nome, e-mail válido e uma senha com pelo menos 8 caracteres.',status:400};if(await env.DB.prepare('SELECT id FROM users WHERE email=?').bind(email).first())return {error:'Não foi possível criar a conta com esses dados.',status:409};const id=uuid(),salt=randomToken(),t=now(),hash=await passwordHash(password,salt);await env.DB.prepare(`INSERT INTO users(id,name,email,password_hash,password_salt,role,plan,created_at,updated_at,last_login_at,last_activity_at) VALUES(?,?,?,?,?,?, 'free',?,?,?,?)`).bind(id,name,email,hash,salt,role,t,t,t,t).run();await event(env,id,'user_registered');return {user:await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(id).first(),token:await createSession(env,id)};}
async function mail(env,message){const key=clean(env.RESEND_API_KEY,300);if(!key)return {ok:false,code:'email_not_configured'};const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{authorization:`Bearer ${key}`,'content-type':'application/json'},body:JSON.stringify(message)});let result={};try{result=await response.json();}catch{}return response.ok?{ok:true,id:result.id||null}:{ok:false,code:'email_provider_error',error:result.message};}
export function validateSupportPayload(input){const payload={nome:clean(input?.nome,80),email:clean(input?.email,160).toLowerCase(),categoria:clean(input?.categoria,80),assunto:clean(input?.assunto,120),mensagem:clean(input?.mensagem,4000)};if(!payload.nome||!validEmail(payload.email)||!payload.assunto||!payload.mensagem)return {ok:false,error:'Preencha nome, e-mail, assunto e mensagem.'};return {ok:true,payload};}
export function avatarType(bytes,declared=''){const b=new Uint8Array(bytes);if(b.length>=3&&b[0]===255&&b[1]===216&&b[2]===255)return declared==='image/jpeg'?'image/jpeg':null;if(b.length>=8&&b.slice(0,8).every((v,i)=>v===[137,80,78,71,13,10,26,10][i]))return declared==='image/png'?'image/png':null;if(b.length>=12&&String.fromCharCode(...b.slice(0,4))==='RIFF'&&String.fromCharCode(...b.slice(8,12))==='WEBP')return declared==='image/webp'?'image/webp':null;return null;}
function needDB(env,request){return env.DB?null:json({ok:false,error:'Banco de dados indisponível.'},503,request);}
function needAuth(user,request){return user?null:json({ok:false,error:'Faça login para continuar.'},401,request);}
function dayKey(t){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(new Date(t));}
async function adminOverview(env,days){const since=now()-days*864e5,users=(await env.DB.prepare('SELECT id,name,email,role,plan,avatar_key,created_at,last_login_at,last_activity_at FROM users ORDER BY created_at DESC LIMIT 500').all()).results||[],events=(await env.DB.prepare('SELECT user_id,event_type,metadata_json,created_at FROM analytics_events WHERE created_at>=? ORDER BY created_at').bind(since).all()).results||[],reports=(await env.DB.prepare('SELECT * FROM question_reports ORDER BY created_at DESC LIMIT 200').all()).results||[],suggestions=(await env.DB.prepare('SELECT * FROM suggestions ORDER BY created_at DESC LIMIT 200').all()).results||[];const today=dayKey(now()),daily={};for(let i=days-1;i>=0;i--){const t=now()-i*864e5;daily[dayKey(t)]={date:dayKey(t),active:new Set(),newUsers:0,correct:0,incorrect:0,skipped:0,started:0,completed:0};}users.forEach(u=>{const d=daily[dayKey(u.created_at)];if(d)d.newUsers++;});for(const e of events){const d=daily[dayKey(e.created_at)];if(!d)continue;if(e.user_id)d.active.add(e.user_id);if(e.event_type==='question_correct')d.correct++;if(e.event_type==='question_incorrect')d.incorrect++;if(e.event_type==='question_skipped')d.skipped++;if(e.event_type==='study_session_started')d.started++;if(e.event_type==='study_session_completed')d.completed++;}const series=Object.values(daily).map(d=>({...d,active:d.active.size})),activeSince=ms=>new Set(events.filter(e=>e.created_at>=now()-ms&&e.user_id).map(e=>e.user_id)).size,count=t=>events.filter(e=>e.event_type===t).length,unique=t=>new Set(events.filter(e=>e.event_type===t).map(e=>e.user_id).filter(Boolean)).size;const registrations=users.length,started=unique('study_session_started'),answered=unique('question_answered'),completed=unique('study_session_completed'),memorized=unique('flashcard_reviewed');const funnel=[['Contas criadas',registrations],['Iniciaram treino',started],['Responderam questão',answered],['Concluíram sessão',completed]];return {period:days,metrics:{online:users.filter(u=>u.last_activity_at>=now()-5*60e3).length,dau:activeSince(864e5),wau:activeSince(7*864e5),mau:activeSince(30*864e5),newToday:users.filter(u=>dayKey(u.created_at)===today).length,answersToday:events.filter(e=>dayKey(e.created_at)===today&&e.event_type==='question_answered').length,sessionsToday:events.filter(e=>dayKey(e.created_at)===today&&e.event_type==='study_session_started').length,completedToday:events.filter(e=>dayKey(e.created_at)===today&&e.event_type==='study_session_completed').length,flashcardsToday:events.filter(e=>dayKey(e.created_at)===today&&e.event_type==='flashcard_reviewed').length},series,funnel:funnel.map((x,i)=>({label:x[0],value:x[1],conversion:i?Math.round(100*x[1]/Math.max(1,funnel[i-1][1])):100})),studyFunnel:[{label:'Criaram conta',value:registrations},{label:'Começaram a estudar',value:started},{label:'Responderam questões',value:answered},{label:'Usaram Memorizar',value:memorized},{label:'Concluíram sessão',value:completed}],users:users.map(u=>({...u,password_hash:undefined,password_salt:undefined,hasAvatar:!!u.avatar_key,avatar_key:undefined})),reports,suggestions,counts:{events:events.length,correct:count('question_correct'),incorrect:count('question_incorrect'),skipped:count('question_skipped')}};}
export function analyticsEventKey(type,meta){const identity=type.startsWith('question_')?([meta.sessionId,meta.questionId].filter(Boolean).join(':')||null):type==='favorite_added'?meta.itemId:(meta.sessionId||null);return identity&&['study_session_started','study_session_completed','question_answered','question_correct','question_incorrect','question_skipped','favorite_added'].includes(type)?`${type}:${identity}`:null;}
// Active means a real authenticated study/navigation event, not merely owning an account.
const ACTIVE_EVENTS=new Set(['study_session_started','study_session_resumed','study_session_completed','question_answered','question_correct','question_incorrect','question_skipped','flashcard_reviewed','topic_viewed','favorite_added','error_vault_viewed','program_2027_viewed']);
