export default {async fetch(request,env={}){const url=new URL(request.url);if(url.pathname==='/api/health')return json({ok:true,databaseConfigured:!!env.DB,avatarStorageConfigured:!!env.AVATARS,emailConfigured:!!clean(env.RESEND_API_KEY,300)},200,request);if(url.pathname.startsWith('/api/')){if(request.method==='OPTIONS')return new Response(null,{status:204,headers:headers(request)});try{return await api(request,env,url);}catch(error){console.error('FIXOU API',error);return json({ok:false,error:'Não foi possível concluir esta operação.',detail:error?.message||null},500,request);}}if(url.pathname==='/support-email'&&request.method==='POST'){const parsed=validateSupportPayload(await body(request));if(!parsed.ok)return json(parsed,400,request);const p=parsed.payload,ok=await mail(env,{from:clean(env.SUPPORT_FROM_EMAIL,200)||'FIXOU <onboarding@resend.dev>',to:[clean(env.SUPPORT_TO_EMAIL,160)||'fixouestudos@gmail.com'],reply_to:p.email,subject:`[FIXOU] ${p.assunto}`,text:`Nome: ${p.nome}\nE-mail: ${p.email}\nCategoria: ${p.categoria||'Outro'}\n\n${p.mensagem}`});return json(ok?{ok:true}:{ok:false,error:'O e-mail ainda não está configurado no backend.'},ok?200:503,request);}if((url.pathname==='/'||url.pathname==='/index.html')&&INDEX_HTML.startsWith('<'))return new Response(INDEX_HTML,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-cache'}});if(url.pathname==='/assets/fixou-logo.png'&&LOGO_BASE64.length>40){const bytes=Uint8Array.from(atob(LOGO_BASE64),c=>c.charCodeAt(0));return new Response(bytes,{headers:{'content-type':'image/png','cache-control':'public, max-age=86400'}});}if(/^\/assets\/app\.[a-f0-9]+\.js$/.test(url.pathname)){if(env.ASSETS?.fetch)return new Response((await env.ASSETS.fetch(request)).body,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'public, max-age=31536000, immutable'}});return new Response('Not found',{status:404});}if(env.ASSETS?.fetch)return env.ASSETS.fetch(request);return new Response('FIXOU backend ativo.',{status:404});}};
